"""Generate packages/contracts/reports.schema.json and reports.ts from the models of the one reports API (job CV, ADR 0088). Same scheme as the other contracts (`make contracts`; a test fails if either file is stale)."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.packs.contracts import _ts_type
from app.reports import models as m

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/reports/models.py. Do not edit.\n"
    "// One shape for every pack's reports: figures, typed tables, series by day. Every figure is a sum or a count of entries a person made.\n"
)
RESPONSES: list[type[BaseModel]] = [m.ReportOut, m.CatalogueOut, m.CatalogueItemOut]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema([(model, "serialization") for model in RESPONSES], ref_template="#/$defs/{model}")
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "reports.schema.json",
        "title": "The reports of every pack, in one shape (job CV)",
        "description": "Generated from services/ai-api/app/reports/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
